syntax:
Class with move constructor and move assignment:

class ClassName {
public:
    // Move constructor
    ClassName(ClassName&& other) noexcept;
    // Move assignment operator
    ClassName& operator=(ClassName&& other) noexcept;
};

// Usage with std::move
#include <utility>

ClassName obj1;
ClassName obj2 = std::move(obj1);
